    question: "JPA vs Hibernate?",
    slug: "jpa-vs-hibernate-131",
    categoryName: "Java",
    categorySlug: "java",
    subcategoryName: "Hibernate & JPA",
    subcategorySlug: "hibernate-jpa",
    experienceLevel: ExperienceLevel.FRESHER,
    difficulty: Difficulty.MEDIUM,
